-- BAD: Locks the table against writes until the index is fully built.
CREATE INDEX idx_user_status ON users(status);

-- GOOD: Builds the index in the background. Does not block INSERT/UPDATE/DELETE.
CREATE INDEX CONCURRENTLY idx_user_status_safe ON users(status);

-- ADVANCED: The Covering Index (Index-Only Scan)
-- Scenario: You frequently query `SELECT email FROM users WHERE status = 'active'`
-- By using INCLUDE, the index stores the email string directly inside the index leaf nodes.
-- The database never has to visit the main table heap, turning O(1) random disk I/Os into O(0).
CREATE INDEX CONCURRENTLY idx_covering_status 
ON users(status) INCLUDE (email);
